<script lang="ts">
    import type { Snippet } from "svelte";

    /**
     * Renders either a string or a snippet.
     */
    let {
        content,
        props,
    }: {
        content?: string | Snippet<[Record<string, any> | undefined]>;
        props?: Record<string, any>;
    } = $props();
</script>

{#if typeof content === 'string'}
    {content}
{:else if content}
    {@render content(props)}
{/if}

